        return []
    if start == goal:
        return [start]

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    visited = set()
    stack = [(start, [start])]

    while stack:
        (current, path) = stack.pop()
        if current == goal:
            return path
        if current in visited:
