def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0]) if rows else 0

    # Check if start or goal is out of bounds or a wall
    if not (0 <= start[0] < rows and 0 <= start[1] < cols):
        return []
    if not (0 <= goal[0] < rows and 0 <= goal[1] < cols):
        return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    # If start is the same as goal
    if start == goal:
        return [start]

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Helper function to check if a cell is valid
    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    # Helper function to find a path using backtracking
    def backtrack(path):
        current = path[-1]
        if current == goal:
            return path.copy()
        for dr, dc in directions:
            next_r, next_c = current[0] + dr, current[1] + dc
            if is_valid(next_r, next_c) and (next_r, next_c) not in path:
                path.append((next_r, next_c))
                result = backtrack(path)
                if result:
                    return result
                path.pop()
        return None

    return backtrack([start])
